SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `users`;
CREATE TABLE users (
            id VARCHAR(255) PRIMARY KEY,
            password TEXT NOT NULL,
            name TEXT NOT NULL,
            role TEXT NOT NULL CHECK(role IN ('superadmin', 'admin', 'teacher', 'student')),
            email TEXT,
            phone TEXT,
            photo TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );



DROP TABLE IF EXISTS `students`;
CREATE TABLE students (
            id VARCHAR(255) PRIMARY KEY,
            grade_level TEXT,
            attendance_percentage REAL DEFAULT 0,
            parent_name TEXT,
            parent_phone TEXT,
            address TEXT,
            dob TEXT, overtime_applicable INTEGER DEFAULT 0, first_admission INTEGER DEFAULT 1,
            FOREIGN KEY (id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `teachers`;
CREATE TABLE teachers (
            id VARCHAR(255) PRIMARY KEY,
            subject TEXT,
            classes TEXT,
            salary INTEGER,
            join_date DATE,
            qualification TEXT,
            FOREIGN KEY (id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `notices`;
CREATE TABLE notices (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            title TEXT NOT NULL,
            date DATE NOT NULL,
            content TEXT NOT NULL,
            priority VARCHAR(255) DEFAULT 'Medium' CHECK(priority IN ('High', 'Medium', 'Low')),
            audience VARCHAR(255) DEFAULT 'all' CHECK(audience IN ('all', 'student', 'teacher')),
            target_class TEXT,
            type VARCHAR(255) DEFAULT 'global',
            author_id VARCHAR(255),
            author_name TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT
        );



DROP TABLE IF EXISTS `tests`;
CREATE TABLE tests (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            name TEXT NOT NULL,
            subject TEXT NOT NULL,
            date DATE NOT NULL,
            total_marks INTEGER NOT NULL,
            section TEXT,
            class_name TEXT,
            teacher_id VARCHAR(255),
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (teacher_id) REFERENCES users(id)
        );



DROP TABLE IF EXISTS `marks`;
CREATE TABLE marks (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            test_id INTEGER,
            student_id VARCHAR(255),
            marks_obtained INTEGER,
            FOREIGN KEY (test_id) REFERENCES tests(id) ON DELETE CASCADE,
            FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `attendance`;
CREATE TABLE attendance (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            user_id VARCHAR(255),
            date DATE NOT NULL,
            status TEXT CHECK(status IN ('present', 'absent')),
            type TEXT CHECK(type IN ('student', 'teacher')),
            FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `classes`;
CREATE TABLE classes (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            name TEXT NOT NULL,
            section TEXT NOT NULL,
            class_teacher_id VARCHAR(255),
            room_number TEXT,
            capacity INTEGER DEFAULT 40, monthly_fee INTEGER DEFAULT 0, annual_dues INTEGER DEFAULT 0, overtime_charges INTEGER DEFAULT 0, other_charges INTEGER DEFAULT 0, admission_fee INTEGER DEFAULT 0, admission_fee_enabled INTEGER DEFAULT 1, annual_fee INTEGER DEFAULT 0, annual_fee_enabled INTEGER DEFAULT 1, tuition_fee INTEGER DEFAULT 0, tuition_fee_enabled INTEGER DEFAULT 1, overtime_fee INTEGER DEFAULT 0, overtime_fee_enabled INTEGER DEFAULT 0, lab_fee INTEGER DEFAULT 0, lab_fee_enabled INTEGER DEFAULT 1, security_charges INTEGER DEFAULT 0, security_charges_enabled INTEGER DEFAULT 1, sports_fee INTEGER DEFAULT 0, sports_fee_enabled INTEGER DEFAULT 0, other_charges_enabled INTEGER DEFAULT 1,
            FOREIGN KEY (class_teacher_id) REFERENCES users(id)
        );



DROP TABLE IF EXISTS `fee_status`;
CREATE TABLE fee_status (
            student_id VARCHAR(255) PRIMARY KEY,
            total INTEGER DEFAULT 5000,
            paid INTEGER DEFAULT 0,
            pending INTEGER DEFAULT 5000,
            FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `student_fees`;
CREATE TABLE student_fees (
            id VARCHAR(255) PRIMARY KEY,
            student_id VARCHAR(255) NOT NULL,
            month TEXT NOT NULL,
            status VARCHAR(255) DEFAULT 'pending' CHECK(status IN ('paid', 'pending', 'overdue', 'partial')),
            amount INTEGER DEFAULT 0,
            proof_url TEXT,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, fee_type VARCHAR(255) DEFAULT 'monthly', due_date TEXT, transaction_id VARCHAR(255), admission_fee INTEGER DEFAULT 0, annual_fee INTEGER DEFAULT 0, tuition_fee INTEGER DEFAULT 0, overtime_fee INTEGER DEFAULT 0, lab_fee INTEGER DEFAULT 0, security_charges INTEGER DEFAULT 0, sports_fee INTEGER DEFAULT 0, other_charges INTEGER DEFAULT 0, arrears INTEGER DEFAULT 0,
            FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `payments`;
CREATE TABLE payments (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            student_id VARCHAR(255) NOT NULL,
            amount INTEGER NOT NULL,
            date DATE NOT NULL,
            method VARCHAR(255) DEFAULT 'cash',
            description TEXT,
            receipt_no TEXT, transaction_id VARCHAR(255), status VARCHAR(255) DEFAULT 'success',
            FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
        );



DROP TABLE IF EXISTS `timetables`;
CREATE TABLE timetables (
            id VARCHAR(255) PRIMARY KEY,
            grade_level VARCHAR(255) NOT NULL UNIQUE,
            data TEXT NOT NULL,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );



DROP TABLE IF EXISTS `messages`;
CREATE TABLE messages (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            from_id VARCHAR(255),
            from_name TEXT,
            to_id VARCHAR(255),
            subject TEXT,
            message TEXT,
            role TEXT,
            date TEXT,
            time TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            is_read INTEGER DEFAULT 0,
            FOREIGN KEY (from_id) REFERENCES users(id) ON DELETE SET NULL
        );



DROP TABLE IF EXISTS `assignments`;
CREATE TABLE assignments (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            title TEXT NOT NULL,
            subject TEXT,
            class_name TEXT,
            due_date DATE,
            message TEXT,
            file_url TEXT,
            teacher_id VARCHAR(255),
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE SET NULL
        );



DROP TABLE IF EXISTS `gallery`;
CREATE TABLE gallery (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            title TEXT,
            image_url TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );



DROP TABLE IF EXISTS `logs`;
CREATE TABLE logs (
            id INTEGER PRIMARY KEY AUTO_INCREMENT,
            action TEXT NOT NULL,
            target_id VARCHAR(255),
            target_name TEXT,
            details TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        );



DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE password_resets (
            email TEXT NOT NULL,
            token TEXT NOT NULL,
            expires_at DATETIME NOT NULL
        );




SET FOREIGN_KEY_CHECKS = 1;
